def apply_transform_simple(inp, bg):
    rows = len(inp)
    cols = len(inp[0])

    events = defaultdict(list)

    for r in range(rows):
        for c in range(cols):
            v = inp[r][c]
            if v != bg:
                events[(r,c)].append((v, 'stay'))
                sr, sc = r-1, c+4
                if sr >= 0 and sc < cols:
                    events[(sr,sc)].append((v, 'shift'))

    output = [[bg] * cols for _ in range(rows)]

    for pos, val_list in events.items():
        r, c = pos
        has_stay = any(evt == 'stay' for val, evt in val_list)
        has_shift = any(evt == 'shift' for val, evt in val_list)

        if has_shift and has_stay:
            win_val = max(v for v, evt in val_list)
            output[r][c] = win_val
        else:
